using System;
using System.Collections.Generic;
using UnityEngine;

namespace VerdantsAscent.Water.Core
{
    /// <summary>
    /// Live runtime overrides for properties on Valheim's Custom/SkyboxProcedural
    /// material. Built to A/B-test which property controls the visible
    /// "horizon-haze band" the user reports at distance — the band is NOT
    /// generated by FiresWater (we verified no horizon math in the shader);
    /// it's the procedural-skybox blending its <c>_SkyTint</c> upper
    /// hemisphere with <c>_GroundColor</c> lower hemisphere through the
    /// <c>_AtmosphereThickness</c>-driven scattering integral, possibly
    /// further modulated by the <c>_FogHeightMin</c>/<c>_FogHeightMax</c>
    /// height-fog band.
    ///
    /// USAGE: Flip <see cref="Enabled"/> via ConfigManager
    /// (FiresWater.SkyboxOverride). With defaults (mul=1, offsets=0, blend=0)
    /// behavior is identical to vanilla — enabling alone changes nothing.
    /// Then tweak each property via the BepInEx ConfigurationManager sliders
    /// in-game and watch the horizon band. Whichever property visibly affects
    /// the band is the responsible one.
    ///
    /// LIFETIME: EnvMan rewrites <c>RenderSettings.skybox</c> on env
    /// transitions (sometimes mid-frame). The driver re-applies overrides
    /// EVERY LateUpdate so a fresh skybox material can't strand our values.
    /// Originals are captured per-material-InstanceID on first sight and
    /// restored on Enabled=false so the user can rollback without restarting.
    ///
    /// SAFETY: We only override materials whose shader is the supported
    /// procedural-skybox name. Custom env skyboxes with other shaders pass
    /// through untouched.
    /// </summary>
    public static class FiresSkyboxDriver
    {
        public const string SupportedShader = "Custom/SkyboxProcedural";

        // Master switch — controlled from ConfigManager.configFiresSkyboxOverride
        // via FiresAdminTerrain.ApplyFiresWaterConfig.
        public static bool Enabled = false;

        // ---- Tunable overrides (default to no-op values) ---------------------

        /// <summary>
        /// Multiplier applied to the captured original <c>_AtmosphereThickness</c>.
        /// 1.0 = unchanged. 0.0 = no atmospheric scattering (sharp horizon
        /// line, no haze). &gt; 1.0 = thicker atmosphere (heavier haze).
        /// </summary>
        public static float AtmosphereThicknessMultiplier = 1.0f;

        /// <summary>
        /// World-meters offset added to the captured original <c>_FogHeightMin</c>.
        /// Push positive to move the bottom of the fog band higher (e.g. above
        /// sea level Y=30 so it doesn't mix with horizon waves).
        /// </summary>
        public static float FogHeightMinOffset = 0f;

        /// <summary>
        /// World-meters offset added to the captured original <c>_FogHeightMax</c>.
        /// </summary>
        public static float FogHeightMaxOffset = 0f;

        /// <summary>
        /// Lerp factor from captured <c>_GroundColor</c> toward captured
        /// <c>_SkyTint</c>. 0.0 = unchanged (vanilla). 1.0 = ground color
        /// exactly matches sky tint (kills the horizon-color discontinuity
        /// between upper and lower hemispheres).
        /// </summary>
        public static float GroundColorBlendToSky = 0f;

        // ---- Aurora glow (Path A) --------------------------------------------
        // Animates _GroundColor through a green→cyan→purple gradient and
        // forces _AtmosphereThickness low at night. When the player looks
        // toward the horizon the procedural skybox's atmospheric scattering
        // makes the colored ground hemisphere bleed up — looks like an
        // aurora-borealis backdrop glow. Real curtain ribbons come from the
        // separate FiresAurora shader (Path B); this is the static backdrop.
        public static bool  AuroraGlowEnabled        = false;
        public static float AuroraGlowIntensity      = 1.0f;
        public static float AuroraGlowSpeed          = 0.05f;
        public static float AuroraGlowAtmosphereMul  = 0.25f;
        public static bool  AuroraGlowNightOnly      = true;

        // The aurora color palette cycles through these stops over time.
        // Tuned for classic green-dominant aurora with cyan/purple accents.
        private static readonly Color[] s_auroraStops = new[]
        {
            new Color(0.05f, 0.95f, 0.35f, 1f),  // green
            new Color(0.15f, 0.85f, 0.75f, 1f),  // cyan-green
            new Color(0.40f, 0.30f, 0.95f, 1f),  // violet-blue
            new Color(0.20f, 0.55f, 0.90f, 1f),  // blue-cyan
            new Color(0.05f, 0.95f, 0.35f, 1f),  // back to green (loops)
        };

        // ---- Internals -------------------------------------------------------

        private struct Original
        {
            public float AtmosphereThickness;
            public float FogHeightMin;
            public float FogHeightMax;
            public Color GroundColor;
            public Color SkyTint;
            public bool  HasAtmosphereThickness;
            public bool  HasFogHeightMin;
            public bool  HasFogHeightMax;
            public bool  HasGroundColor;
            public bool  HasSkyTint;
        }

        // Keyed by Material.GetInstanceID(). EnvMan may share a single
        // skybox material across multiple envs OR instantiate one per env —
        // either way, instance-id keying captures each baseline correctly.
        private static readonly Dictionary<int, Original> s_originals
            = new Dictionary<int, Original>();

        private static readonly int Prop_AtmosphereThickness
            = Shader.PropertyToID("_AtmosphereThickness");
        private static readonly int Prop_FogHeightMin
            = Shader.PropertyToID("_FogHeightMin");
        private static readonly int Prop_FogHeightMax
            = Shader.PropertyToID("_FogHeightMax");
        private static readonly int Prop_GroundColor
            = Shader.PropertyToID("_GroundColor");
        private static readonly int Prop_SkyTint
            = Shader.PropertyToID("_SkyTint");

        /// <summary>
        /// Per-frame entry point. Reads <see cref="RenderSettings.skybox"/>,
        /// captures originals on first sight, then writes either originals
        /// (Enabled=false) or override values (Enabled=true). No-op if the
        /// skybox is null or uses an unsupported shader.
        /// </summary>
        public static void ApplyToActiveSkybox()
        {
            var sky = RenderSettings.skybox;
            if (sky == null || sky.shader == null) return;
            if (sky.shader.name != SupportedShader) return;

            CaptureIfNeeded(sky);
            var orig = s_originals[sky.GetInstanceID()];

            if (!Enabled)
            {
                // Restore originals every frame while disabled. Cheap, and
                // covers the case where the user toggled Enabled off after
                // overrides were applied — without this, our last-written
                // value would persist on the shared material.
                if (orig.HasAtmosphereThickness)
                    sky.SetFloat(Prop_AtmosphereThickness, orig.AtmosphereThickness);
                if (orig.HasFogHeightMin)
                    sky.SetFloat(Prop_FogHeightMin, orig.FogHeightMin);
                if (orig.HasFogHeightMax)
                    sky.SetFloat(Prop_FogHeightMax, orig.FogHeightMax);
                if (orig.HasGroundColor)
                    sky.SetColor(Prop_GroundColor, orig.GroundColor);
                return;
            }

            // Compute aurora gating up-front so we can pick the right
            // _AtmosphereThickness and _GroundColor values.
            bool auroraActive = AuroraGlowEnabled
                && AuroraGlowIntensity > 0.001f
                && (!AuroraGlowNightOnly || IsNight());

            float atmMul = auroraActive
                ? AuroraGlowAtmosphereMul
                : AtmosphereThicknessMultiplier;

            if (orig.HasAtmosphereThickness)
                sky.SetFloat(Prop_AtmosphereThickness,
                    Mathf.Max(0f, orig.AtmosphereThickness * atmMul));
            if (orig.HasFogHeightMin)
                sky.SetFloat(Prop_FogHeightMin, orig.FogHeightMin + FogHeightMinOffset);
            if (orig.HasFogHeightMax)
                sky.SetFloat(Prop_FogHeightMax, orig.FogHeightMax + FogHeightMaxOffset);

            if (orig.HasGroundColor)
            {
                Color target;
                if (auroraActive)
                {
                    // Cycle through stops over time; pulse intensity.
                    float t = Time.unscaledTime * AuroraGlowSpeed;
                    Color cycled = SampleStops(s_auroraStops, t);
                    float pulse  = 0.6f + 0.4f * Mathf.Sin(Time.unscaledTime * 0.35f);
                    target       = cycled * (AuroraGlowIntensity * pulse);
                }
                else if (orig.HasSkyTint)
                {
                    target = Color.Lerp(orig.GroundColor, orig.SkyTint,
                                        Mathf.Clamp01(GroundColorBlendToSky));
                }
                else
                {
                    target = orig.GroundColor;
                }
                sky.SetColor(Prop_GroundColor, target);
            }
        }

        // Linear walk through the color stops, wrapping at the last entry.
        // stops[0] at t=0, stops[N-1] at t=1, wrap to stops[0] at t=N (etc).
        private static Color SampleStops(Color[] stops, float t)
        {
            int n = stops.Length;
            if (n == 0) return Color.black;
            if (n == 1) return stops[0];
            float wrapped = Mathf.Repeat(t, n - 1);
            int   idx     = (int)Mathf.Floor(wrapped);
            float frac    = wrapped - idx;
            return Color.Lerp(stops[idx], stops[Mathf.Min(idx + 1, n - 1)], frac);
        }

        // Vanilla day/night: EnvMan.IsNight() is STATIC. Guard the instance
        // anyway because EnvMan.IsNight reads instance state internally and
        // returns false safely if instance isn't ready.
        private static bool IsNight()
        {
            try { return EnvMan.instance != null && EnvMan.IsNight(); }
            catch { return false; }
        }

        private static void CaptureIfNeeded(Material sky)
        {
            int id = sky.GetInstanceID();
            if (s_originals.ContainsKey(id)) return;

            var orig = new Original
            {
                HasAtmosphereThickness = sky.HasProperty(Prop_AtmosphereThickness),
                HasFogHeightMin        = sky.HasProperty(Prop_FogHeightMin),
                HasFogHeightMax        = sky.HasProperty(Prop_FogHeightMax),
                HasGroundColor         = sky.HasProperty(Prop_GroundColor),
                HasSkyTint             = sky.HasProperty(Prop_SkyTint),
            };
            if (orig.HasAtmosphereThickness)
                orig.AtmosphereThickness = sky.GetFloat(Prop_AtmosphereThickness);
            if (orig.HasFogHeightMin)
                orig.FogHeightMin = sky.GetFloat(Prop_FogHeightMin);
            if (orig.HasFogHeightMax)
                orig.FogHeightMax = sky.GetFloat(Prop_FogHeightMax);
            if (orig.HasGroundColor)
                orig.GroundColor = sky.GetColor(Prop_GroundColor);
            if (orig.HasSkyTint)
                orig.SkyTint = sky.GetColor(Prop_SkyTint);

            s_originals[id] = orig;
            Debug.Log(
                $"[FiresSkyboxDriver] Captured originals for skybox '{sky.name}' " +
                $"(instId={id}): atmThick={orig.AtmosphereThickness:F3}, " +
                $"fogH=[{orig.FogHeightMin:F1}, {orig.FogHeightMax:F1}], " +
                $"groundCol={orig.GroundColor}, skyTint={orig.SkyTint}");
        }
    }

    /// <summary>
    /// Per-frame applier — attach exactly once to a persistent GameObject
    /// (FiresAdminTerrain.RootObject is fine). LateUpdate so the active
    /// skybox material reflects any env-transition rewrite EnvMan made
    /// during the frame.
    /// </summary>
    public class FiresSkyboxDriverComponent : MonoBehaviour
    {
        // Throttle for warning-spam if the skybox material is misconfigured.
        // The driver gets called every frame and Unity property writes
        // shouldn't throw — but defensive code is cheap.
        private int m_lastWarnFrame = -10000;
        private const int WARN_INTERVAL_FRAMES = 600;

        private void LateUpdate()
        {
            try
            {
                FiresSkyboxDriver.ApplyToActiveSkybox();
            }
            catch (Exception ex)
            {
                if (Time.frameCount - m_lastWarnFrame > WARN_INTERVAL_FRAMES)
                {
                    m_lastWarnFrame = Time.frameCount;
                    Debug.LogWarning(
                        $"[FiresSkyboxDriver] ApplyToActiveSkybox failed: {ex.Message}");
                }
            }
        }
    }
}
